"""Business-specific oracle and timing recorder. No scheduling or production state."""
import argparse, copy, hashlib, json, math, pathlib, statistics, sys, time
ROOT = pathlib.Path(__file__).resolve().parents[1]
FIXTURE = ROOT / "tests" / "fixture.json"
ORACLE = ROOT / "tests" / "expected.json"
def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()
def validate(actual, expected):
    errors=[]
    if not isinstance(actual,dict):
        return ["output_not_object"]
    decisions=actual.get("decisions")
    if not isinstance(decisions,list):
        errors.append("decisions_not_list")
    else:
        ids=[x.get("id") if isinstance(x,dict) else None for x in decisions]
        wanted={x["id"]:x["action"] for x in expected["decisions"]}
        if len(ids)!=len(wanted) or len(set(ids))!=len(ids) or set(ids)!=set(wanted):
            errors.append("decision_ids_missing_duplicate_or_extra")
        for x in decisions:
            if isinstance(x,dict) and x.get("id") in wanted and x.get("action")!=wanted[x["id"]]:
                errors.append("wrong_action:"+x["id"])
    ledger=actual.get("ledger")
    if not isinstance(ledger,dict):
        errors.append("ledger_missing")
    else:
        for key,value in expected["ledger"].items():
            got=ledger.get(key)
            if isinstance(value,list):
                if not isinstance(got,list) or len(got)!=len(set(got)) or sorted(got)!=sorted(value):
                    errors.append("wrong_ledger:"+key)
            elif type(got) is not int or got!=value:
                errors.append("wrong_ledger:"+key)
    return errors
def selftest():
    expected=json.loads(ORACLE.read_text(encoding="utf-8"))
    assert validate(copy.deepcopy(expected),expected)==[]
    defects=[]
    for label,mutate in [
      ("missing_tag_decision",lambda x:x["decisions"].pop(5)),
      ("duplicate_case",lambda x:x["decisions"].append(x["decisions"][0])),
      ("wrong_total",lambda x:x["ledger"].update(total_minor=2001)),
      ("float_amount",lambda x:x["ledger"].update(total_minor=2000.0)),
      ("unknown_included",lambda x:x["ledger"]["accepted_ids"].append("E03")),
      ("duplicate_counted",lambda x:x["ledger"]["accepted_ids"].append("E01")),
      ("roi_resumed",lambda x:x["decisions"][27].update(action="COMPUTE_ROI")),
      ("time_start_shifted",lambda x:x["decisions"][26].update(action="ACCEPTED_WALL"))]:
        sample=copy.deepcopy(expected); mutate(sample)
        errs=validate(sample,expected)
        assert errs,label
        defects.append({"defect":label,"rejected":True,"errors":errs})
    result={"status":"PASS","golden":1,"bad_cases":len(defects),"results":defects,
            "clock":vars(time.get_clock_info("perf_counter")),"fixture_sha256":digest(FIXTURE),"oracle_sha256":digest(ORACLE)}
    (ROOT/"tests"/"oracle_selftest.json").write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding="utf-8")
    print(json.dumps({"status":"PASS","bad_cases":len(defects),"clock":result["clock"]}))
def start(token,method):
    target=ROOT/"runs"/token
    if target.exists(): raise ValueError("existing_token_refused")
    target.mkdir()
    methodpath=(ROOT/method).resolve()
    if not methodpath.is_relative_to(ROOT): raise ValueError("method_outside_task")
    data={"token":token,"method_path":method,"method_sha256":digest(methodpath),
          "fixture_sha256":digest(FIXTURE),"oracle_sha256":digest(ORACLE),
          "utc_received_at":time.time_ns(),"monotonic_start_ns":time.perf_counter_ns(),
          "model":"INHERITED_CURRENT_NATIVE_CODEX_NOT_CHANGED","mode":"ONE_NATIVE_AGENT_SERIAL"}
    (target/"start.json").write_text(json.dumps(data,indent=2),encoding="utf-8")
    print(json.dumps({"token":token,"started":True,"start_ns":data["monotonic_start_ns"]}))
def finish(token):
    target=ROOT/"runs"/token
    start=json.loads((target/"start.json").read_text(encoding="utf-8"))
    if (target/"result.json").exists(): raise ValueError("existing_result_refused")
    errors=[]; actual=None
    try:
        actual=json.loads((target/"output.json").read_text(encoding="utf-8-sig"))
        errors+=validate(actual,json.loads(ORACLE.read_text(encoding="utf-8")))
    except Exception as exc: errors.append("output_read_failure:"+type(exc).__name__)
    if digest(FIXTURE)!=start["fixture_sha256"] or digest(ORACLE)!=start["oracle_sha256"]:
        errors.append("input_or_oracle_drift")
    if digest(ROOT/start["method_path"])!=start["method_sha256"]:
        errors.append("method_drift")
    end=time.perf_counter_ns()
    result={**start,"monotonic_end_ns":end,"utc_final_at":time.time_ns(),
            "full_wall_ms":(end-start["monotonic_start_ns"])/1e6,
            "valid":not errors,"errors":errors,"decisions_checked":28,"ledger_rows":12,
            "output_sha256":digest(target/"output.json") if (target/"output.json").exists() else None}
    (target/"result.json").write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding="utf-8")
    print(json.dumps({"token":token,"valid":result["valid"],"full_wall_ms":result["full_wall_ms"],"errors":errors}))
    return 0 if not errors else 1
def micro():
    expected=json.loads(ORACLE.read_text(encoding="utf-8"))
    values=[]
    for _ in range(101):
        t=time.perf_counter_ns()
        actual=json.loads(ORACLE.read_text(encoding="utf-8"))
        assert not validate(actual,expected)
        values.append((time.perf_counter_ns()-t)/1e6)
    result={"scope":"LOCAL_JSON_READ_AND_ORACLE_ONLY_NOT_MODEL_OR_FULL_METHOD","runs":101,
            "min_ms":min(values),"median_ms":statistics.median(values),"p95_ms":sorted(values)[math.ceil(.95*len(values))-1],
            "iterations_per_second":len(values)/(sum(values)/1000)}
    (ROOT/"tests"/"microbenchmark.json").write_text(json.dumps(result,indent=2),encoding="utf-8")
    print(json.dumps(result))
p=argparse.ArgumentParser()
p.add_argument("command",choices=["selftest","start","finish","micro"])
p.add_argument("--token"); p.add_argument("--method")
a=p.parse_args()
if a.command=="selftest":selftest()
elif a.command=="start":start(a.token,a.method)
elif a.command=="finish":sys.exit(finish(a.token))
else:micro()

